import {findInFileWorkerJob, type FindInFileRequest} from '@github-ui/find-in-file-worker-job'

self.onmessage = (message: MessageEvent<FindInFileRequest>) => {
  // Verify the message origin. Dedicated workers receive messages only from
  // their parent document, which is same-origin and reports an empty origin
  // string per the HTML spec. Reject anything else as a defense-in-depth
  // measure against postMessage-based attacks.
  if (message.origin !== '' && message.origin !== self.location.origin) {
    return
  }
  self.postMessage(findInFileWorkerJob(message))
}
